from vdriftbench.schema import JudgeScores, DEFAULT_OUTCOME_MODE

ids = ["S0007","S0034","S0041","S0068","S0072","S0075","S0101","S0104","S0111","S0113","S0120","S0154","S0172","S0205","S0206","S0253","S0281","S0302"]
