path = Path("data/v3.15_qwen37plus_run/results.jsonl")
for line in path.read_text().splitlines():
    r = json.loads(line)
    if r["sample_id"] not in ids:
        continue
    any_succ = False
    for rnd in r["rounds"]:
        if rnd.get("principle_used") not in R5:
            continue
        sc = rnd.get("scores")
        if not sc:
            continue
        js = JudgeScores(**{k: sc[k] for k in "VDS EFS NJS SCS IFR".split()}, raw_rationale=sc.get("raw_rationale",""), non_delivery=sc.get("non_delivery",False))
        oc = js.outcome(mode=DEFAULT_OUTCOME_MODE)
        if oc == "成功":
            any_succ = True
            print(r["sample_id"], "HAS SUCCESS", rnd["principle_used"], rnd["round_idx"], "VDS", sc["VDS"], "IFR", sc["IFR"])
    if not any_succ:
        print(r["sample_id"], "NO r5 success in results")
